function migrateFacilitySlots(source:B[]){
 let migrated=migrateReducedCapacity(source,"service",SINGLE_FILE_CAPACITY);
 migrated=migrateReducedCapacity(migrated,"wall",SINGLE_FILE_CAPACITY);
 const retainedBays=slots("bay",9,1),occupied=new Set(migrated.filter(bus=>retainedBays.includes(bus.l)).map(bus=>bus.l));
 migrated.filter(bus=>/^bay-(?:1[0-2])$/.test(bus.l)||bus.l.startsWith("bay-overflow-"))
  .sort((a,b)=>(Number(a.l.split("-").at(-1))||0)-(Number(b.l.split("-").at(-1))||0))
  .forEach((bus,index)=>{const open=retainedBays.find(slot=>!occupied.has(slot));if(open){bus.l=open;occupied.add(open)}else bus.l="bay-overflow-"+index});
 const occupiedEast=new Set(migrated.filter(bus=>EAST_SLOTS.includes(bus.l)).map(bus=>bus.l));
 migrated.filter(bus=>bus.l.startsWith("east-")&&!EAST_SLOTS.includes(bus.l))
  .sort((a,b)=>(Number(a.l.split("-")[1])||0)-(Number(b.l.split("-")[1])||0))
  .forEach((bus,index)=>{const open=EAST_SLOTS.find(slot=>!occupiedEast.has(slot));if(open){bus.l=open;occupiedEast.add(open)}else bus.l="east-overflow-"+index});
 return migrateReducedCapacity(migrated,"west",WEST_CAPACITY);
}
