 useEffect(()=>{if(!adding)return;const frame=requestAnimationFrame(()=>pickerRef.current?.scrollIntoView({block:"nearest",behavior:"smooth"}));return()=>cancelAnimationFrame(frame)},[adding,d.defects.length]);useEffect(()=>{if(!newDefect.category)return;const frame=requestAnimationFrame(()=>secondaryRepairRef.current?.scrollIntoView({block:"nearest",inline:"nearest",behavior:"smooth"}));return()=>cancelAnimationFrame(frame)},[newDefect.category]);useEffect(()=>{if(!repairGroup)return;const frame=requestAnimationFrame(()=>tertiaryRepairRef.current?.scrollIntoView({block:"nearest",inline:"nearest",behavior:"smooth"}));return()=>cancelAnimationFrame(frame)},[repairGroup]);useEffect(()=>{if(newDefect.category==="Interior Cleaning"&&newDefect.issue)setNewDefect(current=>({...current,operability:defaultDefectOperability(current.category,current.issue)}))},[newDefect.category,newDefect.issue]);
 const applyDefects=(defects:StructuredDefect[])=>setD(current=>{const next={...current,defects,pendingRepair:defectSummary(defects)},smartArea=current.l.startsWith("road-")||current.l.startsWith("garage-");return smartStatusEnabled&&smartArea?{...next,s:statusForLocation(current.l,current.s,next) as S}:next});
