function ColorField({label,value,onChange}:{label:string;value:string;onChange:(value:string)=>void}){return <label className="color-field"><span>{label}</span><input type="color" value={value} onChange={event=>onChange(event.target.value)}/><code>{value.toUpperCase()}</code></label>}
function FleetCreationControl({buses,areas,createBus}:{buses:B[];areas:AreaChoice[];createBus:(number:string,status:S,area:string)=>boolean}){const [number,setNumber]=useState(""),[status,setStatus]=useState<S>("service"),[area,setArea]=useState("");const submit=(event:React.FormEvent)=>{event.preventDefault();if(createBus(number,status,area)){setNumber("");setStatus("service");setArea("")}};return <section className="settings-group fleet-creation-control"><div className="fleet-total"><span>ACTIVE TRACKER FLEET</span><b>{buses.length}</b><small>TOTAL BUSES</small></div><h3>CREATE NEW BUS</h3><p>New fleet units can only be created here. The number must be unique and the starting area must have an open space.</p><form className="fleet-create-row" onSubmit={submit}><label>NEW BUS NUMBER<input required inputMode="numeric" value={number} onChange={event=>setNumber(event.target.value.replace(/\D/g,""))} placeholder="Bus #"/></label><label>STARTING STATUS<select value={status} onChange={event=>setStatus(event.target.value as S)}>{Object.entries(ST).map(([key,value])=><option value={key} key={key}>{value[0]}</option>)}</select></label><label>INITIAL AREA<select required value={area} onChange={event=>setArea(event.target.value)}><option value="">Choose an open area</option>{areas.map(choice=><option value={choice.name} disabled={!choice.available} key={choice.name}>{choice.name}{choice.available?"":" - FULL"}</option>)}</select></label><button type="submit">CREATE BUS</button></form><div className="fleet-warning">Creating a fleet unit is an administrative action. Map spaces only relocate buses that already exist.</div></section>}
function FleetNumberControl({buses,renameBus}:{buses:B[];renameBus:(id:string,number:string)=>boolean}){const ordered=[...buses].sort((a,b)=>a.n.localeCompare(b.n,undefined,{numeric:true})),[selectedId,setSelectedId]=useState(ordered[0]?.id||""),selected=ordered.find(bus=>bus.id===selectedId)||ordered[0],[number,setNumber]=useState(selected?.n||"");const choose=(id:string)=>{setSelectedId(id);setNumber(ordered.find(bus=>bus.id===id)?.n||"")};return <section className="settings-group fleet-number-control"><h3>FLEET NUMBER CONTROL</h3><p>Bus numbers are protected in the regular editor. Use this controlled area only for an authorized fleet-number correction.</p>{selected?<div className="fleet-number-row"><label>SELECT BUS<select value={selected.id} onChange={event=>choose(event.target.value)}>{ordered.map(bus=><option value={bus.id} key={bus.id}>Bus {bus.n||"New"} — {ST[bus.s][0]}</option>)}</select></label><label>AUTHORIZED NEW NUMBER<input inputMode="numeric" value={number} onChange={event=>setNumber(event.target.value.replace(/\D/g,""))}/></label><button type="button" onClick={()=>{if(renameBus(selected.id,number))setNumber(number.trim())}}>UPDATE NUMBER</button></div>:<p>No buses are available.</p>}<div className="fleet-warning">Changing a fleet number is a protected administrative action. Duplicate numbers are blocked.</div></section>}
function StatusSettings({buses,areas,busDisplay,setBusDisplay,singleTapEmptySpaces,setSingleTapEmptySpaces,confirmMoves,setConfirmMoves,confirmDefects,setConfirmDefects,createBus,renameBus,colors,setColors,visuals,setVisuals,themeName,setThemeName,applyTheme,exportBoard,importBoard,close}:{buses:B[];areas:AreaChoice[];busDisplay:BusDisplayMode;setBusDisplay:(value:BusDisplayMode)=>void;singleTapEmptySpaces:boolean;setSingleTapEmptySpaces:(value:boolean)=>void;confirmMoves:boolean;setConfirmMoves:(value:boolean)=>void;confirmDefects:boolean;setConfirmDefects:(value:boolean)=>void;createBus:(number:string,status:S,area:string)=>boolean;renameBus:(id:string,number:string)=>boolean;colors:Record<S,string>;setColors:React.Dispatch<React.SetStateAction<Record<S,string>>>;visuals:Visuals;setVisuals:React.Dispatch<React.SetStateAction<Visuals>>;themeName:string;setThemeName:(value:string)=>void;applyTheme:(name:string)=>void;exportBoard:()=>void;importBoard:(event:React.ChangeEvent<HTMLInputElement>)=>void;close:()=>void}){
 const manualVisual=(key:Exclude<keyof Visuals,"sections">,value:string)=>{setThemeName("custom");setVisuals(current=>({...current,[key]:value}))};
 const manualSection=(key:SectionThemeKey,value:string)=>{setThemeName("custom");setVisuals(current=>({...current,sections:{...current.sections,[key]:value}}))};
 const manualStatus=(status:S,value:string)=>{setThemeName("custom");setColors(current=>({...current,[status]:value}))};
 const globalFields=[["page","Page Background"],["panel","Panel Background"],["text","Main Text"],["header","Header Background"],["headerText","Header Text"],["title","Section Title Text"],["border","Borders / Lines"],["slot","Parking Spaces"],["command","Command Bar"],["commandText","Command Text"]] as const;
 return <div className="shade settings-shade" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><section className="settings-modal"><div className="mhead"><span>ADMINISTRATIVE SETTINGS<h2>Dashboard Settings</h2></span><button onClick={close}>X</button></div><div className="settings-body"><section className="settings-group board-data"><h3>BOARD BACKUP &amp; TRANSFER</h3><p>Move this device's complete board to another browser, Home Screen app, iPad, or phone. Export first, then import that file on the destination device.</p><div><button type="button" onClick={exportBoard}>EXPORT / SHARE BACKUP</button><label>IMPORT BACKUP<input type="file" accept=".json,application/json" onChange={importBoard}/></label></div><small>Import replaces the destination device's current board only after you confirm it.</small></section><section className="settings-group touch-control-settings bus-display-settings"><h3>BUS MARKER DISPLAY</h3><p>Choose how buses appear inside parking spaces on this device.</p><label><input type="checkbox" checked={busDisplay==="number"} onChange={event=>setBusDisplay(event.target.checked?"number":"icon")}/><span><b>SHOW LARGE NUMBER TILES INSTEAD OF BUS ICONS</b><small>Off shows the current bus icon and number. On shows a larger number-only tile while keeping status colors and alerts.</small></span></label></section><section className="settings-group touch-control-settings"><h3>TOUCH CONTROLS</h3><p>Desktop empty spaces always open with one mouse click. On iPad and iPhone, double tap is the safer default.</p><label><input type="checkbox" checked={singleTapEmptySpaces} onChange={event=>setSingleTapEmptySpaces(event.target.checked)}/><span><b>ALLOW SINGLE-TAP EMPTY SPACES ON TOUCHSCREENS</b><small>Leave this off to require two taps on the same empty parking space.</small></span></label></section><section className="settings-group touch-control-settings confirmation-settings"><h3>CONFIRMATION PROMPTS</h3><p>Choose whether this device asks Are you sure before applying a change. Turning a prompt off makes the action happen immediately.</p><label><input type="checkbox" checked={confirmMoves} onChange={event=>setConfirmMoves(event.target.checked)}/><span><b>CONFIRM BUS MOVES &amp; SWITCHES</b><small>Covers Move Bus Here on an empty space, Switch / Reassign in the bus editor, and Move All in the multi-bus tool. Drag and drop never asks.</small></span></label><label><input type="checkbox" checked={confirmDefects} onChange={event=>setConfirmDefects(event.target.checked)}/><span><b>CONFIRM GROUP DEFECT ASSIGNMENT</b><small>Covers adding the same defect to every selected bus in the multi-bus tool.</small></span></label><small className="confirmation-note">Importing a backup always asks, because it replaces this device's whole board.</small></section><FleetCreationControl buses={buses} areas={areas} createBus={createBus}/><FleetNumberControl buses={buses} renameBus={renameBus}/><section className="settings-group"><h3>THEMES</h3><p>Apply a complete dashboard and bus-color preset. You can fine-tune anything below.</p><div className="theme-grid">{Object.entries(THEMES).map(([key,preset])=><button className={themeName===key?"active":""} key={key} onClick={()=>applyTheme(key)}><i style={{background:preset.visuals.page,borderColor:preset.visuals.border}}/><b>{preset.label}</b></button>)}</div>{themeName==="custom"&&<div className="custom-theme-badge">CUSTOM MANUAL COLORS</div>}</section><section className="settings-group"><h3>MANUAL DASHBOARD COLORS</h3><div className="manual-grid">{globalFields.map(([key,label])=><ColorField key={key} label={label} value={visuals[key]} onChange={value=>manualVisual(key,value)}/>)}</div></section><section className="settings-group garage-color-settings"><h3>MAIN GARAGE APPEARANCE</h3><p>Give Bays 11 and 12 a distinct parking-space shade and control the garage border, bay-number banner, and row banners together.</p><div className="manual-grid"><ColorField label="Bays 11 & 12 Parking Spaces" value={visuals.garageSpecial} onChange={value=>manualVisual("garageSpecial",value)}/><ColorField label="Mystery Spaces" value={visuals.mysterySlot} onChange={value=>manualVisual("mysterySlot",value)}/><ColorField label="Garage Border, Top & Row Banners" value={visuals.garageFrame} onChange={value=>manualVisual("garageFrame",value)}/></div></section><section className="settings-group"><h3>SECTION BACKGROUNDS</h3><div className="manual-grid section-color-grid">{SECTION_THEME_KEYS.map(([key,label])=><ColorField key={key} label={label} value={visuals.sections[key]} onChange={value=>manualSection(key,value)}/>)}</div></section><section className="settings-group"><h3>BUS STATUS COLORS</h3><div className="manual-grid status-color-grid">{(Object.keys(ST) as S[]).map(status=><label className="color-field status-field" key={status}><span><Icon s={status}/>{ST[status][0]}</span><input type="color" value={colors[status]} onChange={event=>manualStatus(status,event.target.value)}/><code>{colors[status].toUpperCase()}</code></label>)}</div></section></div><div className="settings-actions"><button onClick={()=>applyTheme("default")}>RESET ALL</button><button className="save" onClick={close}>DONE</button></div></section></div>}
function RemoveBusPicker({name,buses,close,remove}:{name:string;buses:B[];close:()=>void;remove:(id:string)=>void}){return <div className="shade remove-shade" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="remove-modal"><div className="mhead"><span>SECTION BUSES<h2>{name}</h2></span><button onClick={close}>X</button></div><div className="remove-list">{buses.length===0?<p>No buses are currently assigned to this section.</p>:buses.map(bus=><div key={bus.id}><span><Icon s={bus.s}/><b>Bus {bus.n||"New"}</b><small>{ST[bus.s][0]}</small></span><button onClick={()=>remove(bus.id)}>REMOVE</button></div>)}</div><div className="settings-actions"><span/><button className="save" onClick={close}>DONE</button></div></section></div>}
